edits.newText:
_Cycle('void-settings-screen', 'screen', labelFor(cfg.type), cycleScreen),
// Cassette: show its variant controls immediately after the screen
// picker (no DISPLAY header intervening).
if (cfg is CassetteScreenConfig) ...[
  ...displayRows(cfg),
  if (cfg.variant == CassetteVariant.v3)
    _Cycle(
      'void-settings-cassette-color-scheme',
      'color scheme',
      spectrum.colorScheme.label,
      () => settings.saveSettings(
        spectrum.copyWith(
          colorScheme: _next(
            SpectrumColorScheme.values,
            spectrum.colorScheme,
          ),
        ),
      ),
    ),
],
_Toggle('void-settings-immersive', 'immersive',
    settings.immersiveNotifier.value,
    () => settings.setImmersive(!settings.immersiveNotifier.value)),

_Group('DISPLAY'),
if (kDebugMode || (!kIsWeb && Platform.isMacOS))
  _Toggle('void-settings-debug-layout', 'debug layout',
      settings.debugLayoutNotifier.value, settings.toggleDebugLayout),
if (cfg is! CassetteScreenConfig) ...displayRows(cfg),

